mapper.delete:
DELETE FROM reauth_tokens
WHERE token_hash = #{tokenHash}
    AND user_id = #{userId}
    AND session_id = #{sessionId}
    AND purpose = #{purpose}
    AND target_id = #{targetId}
    AND expires_at > clock_timestamp()
